package com.ptms.controller; import com.ptms.dto.*; import com.ptms.service.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/employees") public class EmployeeController{private final EmployeeService s;public EmployeeController(EmployeeService s){this.s=s;}@GetMapping public List<EmployeeDto>all(){return s.all();}@PostMapping public EmployeeDto save(@Valid @RequestBody EmployeeDto d){return s.save(d);}@PutMapping("/{id}") public EmployeeDto update(@PathVariable Long id,@Valid @RequestBody EmployeeDto d){return s.save(new EmployeeDto(id,d.employeeCode(),d.name(),d.vehicleNumber(),d.team(),d.department(),d.parkingPass(),d.defaultEntryTime()));}@DeleteMapping("/{id}") public void delete(@PathVariable Long id){s.delete(id);}}
